    private static func enableColoring(_ score: Score) {
        let shuffledHues: List<Double> = List<Double>(0.38, 0.88, 0.04, 0.0, 0.08, 0.36, 0.48, 0.94, 0.64, 0.72, 0.76, 0.34, 0.44, 0.02, 0.56, 0.1, 0.7, 0.66, 0.96, 0.68, 0.16, 0.5, 0.46, 0.3, 0.4, 0.26, 0.92, 0.2, 0.24, 0.42, 0.58, 0.74, 0.8, 0.84, 0.22, 0.32, 0.28, 0.12, 0.9, 0.18, 0.14, 0.54, 0.6, 0.62, 0.86, 0.52, 0.78, 0.82, 0.06, 0.98)
        var hueIndex: Double = 0.0
        var saturation: Double = 1.0
        var lightness: Double = 0.5
        func hueToRgb(_ p: Double, _ q: Double, _ t: Double) -> Double {
            var paramt = t
            if paramt < 0 {
                paramt += 1.0
            }
            if paramt > 1 {
                paramt -= 1.0
            }
            if paramt < 1.0 / 6.0 {
                return p + (q - p) * 6.0 * paramt
            }
            if paramt < 1.0 / 2.0 {
