            }
            if paramt < 2.0 / 3.0 {
                return p + (q - p) * (2.0 / 3.0 - paramt) * 6.0
            }
            return p
        }
        func randomColor() -> Color {
            hueIndex += 1
            if hueIndex >= shuffledHues.length {
                hueIndex = 0.0
                saturation -= 0.05
                if saturation <= 0 {
                    saturation = 1.0
                    lightness -= 0.05
                    if lightness < 0 {
