            }
            let h: Double = shuffledHues[(hueIndex).toInt()]
            let q: Double = lightness < 0.5 ? lightness * (1.0 + saturation) : lightness + saturation - lightness * saturation
            let p: Double = 2.0 * lightness - q
            let r: Double = hueToRgb(p, q, h + 1.0 / 3.0)
            let g: Double = hueToRgb(p, q, h)
            let b: Double = hueToRgb(p, q, h - 1.0 / 3.0)
            return Color(jsOr(r * 255.0, 0), jsOr(g * 255.0, 0), jsOr(b * 255.0, 0))
        }
